Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
typedef pair<LL, LL> Pair;

const int LIMIT = 100002;
const LL INFINITY_VAL = 1000000007;
const long double TOL = 1e-15;

LL x_in, y_in, max_b;
long double min_diff = INFINITY_VAL;
Pair best;

void update_if_better(LL b, LL a) {
    long double diff = fabs((long double)a / b - (long double)x_in / y_in);
    if (diff + TOL < min_diff) {
        min_diff = diff;
        best = {b, a};
    }
}

int main() {
    cin >> x_in >> y_in >> max_b;
    for (LL b = 1; b <= max_b; ++b) {
        LL a_floor = (x_in * b) / y_in;
        LL a_ceil = a_floor + 1;
        update_if_better(b, a_floor);
        update_if_better(b, a_ceil);
    }
    cout << best.second << '/' << best.first;
    return 0;
}
